{
  "context": "Antibody-phage selection comparing helper phages CM13d3 and M13KO7.",
  "pre_synthesized_answer": "Ground the comparison in helper-phage selection behavior and look for evidence on how CM13d3 vs M13KO7 may change phage-display output in antibody selections.",
  "logic_list": [
    {
      "reasoning_type": "abductive",
      "logic": "The best current hypothesis is that helper-phage choice may change selection output, so evidence is being sought."
    }
  ]
}

